from playwright.sync_api import sync_playwright
from pathlib import Path
p=Path(__file__).resolve().parent; shots=p/'hyperframes'/'screens';shots.mkdir(exist_ok=True)
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']); page=b.new_page(viewport={'width':412,'height':915},device_scale_factor=2,is_mobile=True,has_touch=True); errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.set_content((p/'../Cinemana-Liquid-Glass-V4.html').read_text());page.wait_for_timeout(650)
 def shot(name):
  page.wait_for_timeout(480);page.locator('#toast').evaluate("el=>el.classList.remove('show')");page.wait_for_timeout(260);page.screenshot(path=str(shots/(name+'.png')));assert page.locator('body').evaluate('(el)=>el.scrollWidth <= innerWidth+1'),name
 shot('home');page.locator('.dock [data-page=search]').click();page.locator('#search-input').fill('ناروتو');assert page.locator('#results .poster').count()==1;shot('search');page.locator('#results .poster').click();shot('detail');page.locator('[data-action=batch]').click();shot('batch');page.locator('[data-action=batch-add]').click();assert page.locator('.download-row').count()>=5;shot('downloads');page.locator('.download-row [data-toggle]').first.click();assert page.locator('.download-row [data-toggle] svg').first.count()==1;page.locator('.dock [data-page=account]').click();page.locator('[data-page=settings]').click();shot('settings');page.locator('[data-action=appearance]').click();page.locator('[data-theme=light]').click();page.locator('[data-action=close]').click();shot('light');page.locator('[data-setting=glass]').click();assert page.locator('body').evaluate("e=>e.classList.contains('no-glass')");page.locator('#theme').click();page.locator('#theme').click();page.locator('.dock [data-page=library]').click();shot('library');assert not errors,errors;print('PASS: offline HTML, 8 screens, search, detail, batch, queue, pause, theme, glass, navigation; no JS errors');b.close()
